CREATE TABLE IF NOT EXISTS SchemaMigration (version INTEGER PRIMARY KEY, appliedAt TEXT NOT NULL);
CREATE TABLE Profile (id TEXT PRIMARY KEY, name TEXT NOT NULL, level TEXT NOT NULL, path TEXT NOT NULL, createdAt TEXT NOT NULL, updatedAt TEXT NOT NULL);
CREATE TABLE SeedMarker (name TEXT PRIMARY KEY, appliedAt TEXT NOT NULL);
CREATE TABLE UserSettings (profileId TEXT PRIMARY KEY REFERENCES Profile(id) ON DELETE CASCADE, coachName TEXT NOT NULL, goalMinutes INTEGER NOT NULL CHECK(goalMinutes BETWEEN 5 AND 300), updatedAt TEXT NOT NULL);
CREATE TABLE LearningModule (id TEXT PRIMARY KEY, content TEXT NOT NULL CHECK(json_valid(content)));
CREATE TABLE Lesson (id TEXT PRIMARY KEY, moduleId TEXT NOT NULL REFERENCES LearningModule(id), content TEXT NOT NULL CHECK(json_valid(content)));
CREATE TABLE Exercise (id TEXT PRIMARY KEY, content TEXT NOT NULL CHECK(json_valid(content)));
CREATE TABLE TechniqueCard (id TEXT PRIMARY KEY, content TEXT NOT NULL CHECK(json_valid(content)));
CREATE TABLE ReferenceResource (id TEXT PRIMARY KEY, techniqueCardId TEXT REFERENCES TechniqueCard(id), content TEXT NOT NULL CHECK(json_valid(content)));
CREATE TABLE Equipment (id TEXT PRIMARY KEY, profileId TEXT NOT NULL REFERENCES Profile(id) ON DELETE CASCADE, kind TEXT NOT NULL CHECK(kind IN ('machine','cartridge','ink')), content TEXT NOT NULL CHECK(json_valid(content)), createdAt TEXT NOT NULL, updatedAt TEXT NOT NULL);
CREATE INDEX Equipment_owner ON Equipment(profileId);
CREATE TABLE Cartridge (equipmentId TEXT PRIMARY KEY REFERENCES Equipment(id) ON DELETE CASCADE, code TEXT NOT NULL, configuration TEXT NOT NULL);
CREATE TABLE Ink (equipmentId TEXT PRIMARY KEY REFERENCES Equipment(id) ON DELETE CASCADE, purpose TEXT NOT NULL, expiresAt TEXT NOT NULL);
CREATE TABLE LessonProgress (id TEXT PRIMARY KEY, profileId TEXT NOT NULL REFERENCES Profile(id) ON DELETE CASCADE, lessonId TEXT NOT NULL REFERENCES Lesson(id), completedAt TEXT NOT NULL, UNIQUE(profileId,lessonId));
CREATE TABLE PracticeSession (id TEXT PRIMARY KEY, profileId TEXT NOT NULL REFERENCES Profile(id) ON DELETE CASCADE, exerciseId TEXT NOT NULL REFERENCES Exercise(id), content TEXT NOT NULL CHECK(json_valid(content)), createdAt TEXT NOT NULL, updatedAt TEXT NOT NULL);
CREATE INDEX PracticeSession_owner ON PracticeSession(profileId);
CREATE TABLE PracticePhoto (id TEXT PRIMARY KEY, profileId TEXT NOT NULL REFERENCES Profile(id) ON DELETE CASCADE, sessionId TEXT NOT NULL REFERENCES PracticeSession(id) ON DELETE CASCADE, filename TEXT UNIQUE NOT NULL, mimeType TEXT NOT NULL, width INTEGER NOT NULL, height INTEGER NOT NULL, size INTEGER NOT NULL, createdAt TEXT NOT NULL);
CREATE TABLE SkillAssessment (id TEXT PRIMARY KEY, profileId TEXT NOT NULL REFERENCES Profile(id) ON DELETE CASCADE, sessionId TEXT UNIQUE NOT NULL REFERENCES PracticeSession(id) ON DELETE CASCADE, content TEXT NOT NULL CHECK(json_valid(content)), updatedAt TEXT NOT NULL);
CREATE TABLE DesignProject (id TEXT PRIMARY KEY, profileId TEXT NOT NULL REFERENCES Profile(id) ON DELETE CASCADE, content TEXT NOT NULL CHECK(json_valid(content)), createdAt TEXT NOT NULL, updatedAt TEXT NOT NULL);
CREATE TABLE CoachingSession (id TEXT PRIMARY KEY, profileId TEXT NOT NULL REFERENCES Profile(id) ON DELETE CASCADE, content TEXT NOT NULL CHECK(json_valid(content)), createdAt TEXT NOT NULL);
CREATE TABLE Goal (id TEXT PRIMARY KEY, profileId TEXT NOT NULL REFERENCES Profile(id) ON DELETE CASCADE, content TEXT NOT NULL CHECK(json_valid(content)), createdAt TEXT NOT NULL, updatedAt TEXT NOT NULL);
